using Bank.Payments.Domain.Model;
using Bank.Payments.Domain.Port;
using Bank.Payments.Infrastructure;

namespace Bank.Payments.Adapters.Out.Sql;

/// <summary>ADO.NET adapter of the port PaymentOrderRepository (table payment_order).</summary>
public sealed class SqlPaymentOrderRepository(Db db) : PaymentOrderRepository
{
    public PaymentOrder? FindByNumberAndCompany(int? orderNumber, int? companyId)
    {
        using var command = db.Command(
            "SELECT order_number, company_id, status, payment_date, commission " +
            "FROM payment_order WHERE order_number = @orderNumber AND company_id = @companyId");
        command.Parameters.AddWithValue("@orderNumber", (object?)orderNumber ?? DBNull.Value);
        command.Parameters.AddWithValue("@companyId", (object?)companyId ?? DBNull.Value);
        using var reader = command.ExecuteReader();
        if (!reader.Read())
        {
            return null;
        }

        return new PaymentOrder(
            reader.IsDBNull(0) ? null : reader.GetInt32(0),
            reader.IsDBNull(1) ? null : reader.GetInt32(1),
            reader.IsDBNull(2) ? null : reader.GetString(2),
            reader.IsDBNull(3) ? null : reader.GetDateTime(3),
            reader.IsDBNull(4) ? null : reader.GetDecimal(4));
    }

    public int MarkPaid(int? orderNumber, int? companyId, DateTime? paymentDate, decimal? commission)
    {
        using var command = db.Command(
            "UPDATE payment_order SET status = 'A', payment_date = @paymentDate, commission = @commission " +
            "WHERE order_number = @orderNumber AND company_id = @companyId");
        command.Parameters.AddWithValue("@paymentDate", (object?)paymentDate ?? DBNull.Value);
        command.Parameters.AddWithValue("@commission", (object?)commission ?? DBNull.Value);
        command.Parameters.AddWithValue("@orderNumber", (object?)orderNumber ?? DBNull.Value);
        command.Parameters.AddWithValue("@companyId", (object?)companyId ?? DBNull.Value);
        return command.ExecuteNonQuery();
    }
}
